def cobs_encode(data):
    out = bytearray()
    block = bytearray()
    for byte in data:
        if byte == 0:
            out.append(len(block) + 1)
            out += block
            block = bytearray()
        else:
            block.append(byte)
            if len(block) == 254:
                out.append(255)
                out += block
                block = bytearray()
    out.append(len(block) + 1)
    out += block
    return bytes(out)


def cobs_decode(data):
    out = bytearray()
    i = 0
    n = len(data)
    while i < n:
        code = data[i]
        if code == 0:
            raise ValueError("zero byte in encoded input")
        i += 1
        end = i + code - 1
        if end > n:
            raise ValueError("group data runs past end of input")
        block = data[i:end]
        if 0 in block:
            raise ValueError("zero byte in encoded input")
        out += block
        i = end
        if code < 255 and i < n:
            out.append(0)
    return bytes(out)
