class Reassembler:
    _SCAN, _SYNC2, _LEN_LO, _LEN_HI, _PAYLOAD, _CHECK = range(6)

    def __init__(self):
        self._state = self._SCAN
        self._len_lo = 0
        self._need = 0
        self._buf = bytearray()

    def feed(self, chunk: bytes) -> list[bytes]:
        out = []
        for b in chunk:
            s = self._state
            if s == self._SCAN:
                if b == 0xAA:
                    self._state = self._SYNC2
            elif s == self._SYNC2:
                if b == 0x55:
                    self._state = self._LEN_LO
                elif b == 0xAA:
                    self._state = self._SYNC2
                else:
                    self._state = self._SCAN
            elif s == self._LEN_LO:
                self._len_lo = b
                self._state = self._LEN_HI
            elif s == self._LEN_HI:
                length = self._len_lo | (b << 8)
                self._buf = bytearray()
                if length > 4096:
                    self._state = self._SCAN
                elif length == 0:
                    self._state = self._CHECK
                else:
                    self._need = length
                    self._state = self._PAYLOAD
            elif s == self._PAYLOAD:
                self._buf.append(b)
                self._need -= 1
                if self._need == 0:
                    self._state = self._CHECK
            else:  # _CHECK
                x = 0
                for p in self._buf:
                    x ^= p
                if x == b:
                    out.append(bytes(self._buf))
                self._buf = bytearray()
                self._state = self._SCAN
        return out
