double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad)
{
    const int nW1 = n_hidden * n_in;
    const int n_total = nW1 + n_hidden + n_hidden + 1;

    // Overwrite (zero) grad every call
    for (int i = 0; i < n_total; ++i) grad[i] = 0.0;

    double loss = 0.0;
    double* h = new double[n_hidden];

    for (int s = 0; s < n_samples; ++s) {
        const double* x  = X + (long long)s * n_in;
        const double* W1 = params;
        const double* b1 = params + nW1;
        const double* W2 = b1 + n_hidden;
        const double  b2 = W2[n_hidden];

        // ---- Forward pass ----
        for (int j = 0; j < n_hidden; ++j) {
            double pre = b1[j];
            const double* W1row = W1 + (long long)j * n_in;
            for (int k = 0; k < n_in; ++k) pre += W1row[k] * x[k];
            h[j] = std::tanh(pre);
        }

        double z = b2;
        for (int j = 0; j < n_hidden; ++j) z += W2[j] * h[j];

        const double p = 1.0 / (1.0 + std::exp(-z));

        // Clamped p for numerically safe log (gradient below stays analytic)
        double pc = p;
        if (pc < 1e-12) pc = 1e-12;
        if (pc > 1.0 - 1e-12) pc = 1.0 - 1e-12;
        loss += -(y[s] * std::log(pc) + (1.0 - y[s]) * std::log(1.0 - pc));

        // ---- Backward pass (accumulate into grad) ----
        const double dz = p - y[s];

        // b2 gradient
        grad[nW1 + 2 * n_hidden] += dz;

        for (int j = 0; j < n_hidden; ++j) {
            // W2 gradient
            grad[nW1 + n_hidden + j] += dz * h[j];

            // dL/d(pre_j) = dz * W2[j] * (1 - h_j^2)
            const double dhpre = dz * W2[j] * (1.0 - h[j] * h[j]);

            // b1 gradient
            grad[nW1 + j] += dhpre;

            // W1 gradient
            double* grow = grad + (long long)j * n_in;
            for (int k = 0; k < n_in; ++k) grow[k] += dhpre * x[k];
        }
    }

    delete[] h;

    // Average over samples
    const double inv = 1.0 / (double)n_samples;
    loss *= inv;
    for (int i = 0; i < n_total; ++i) grad[i] *= inv;

    return loss;
}
