struct Tape {
    struct Node {
        double v;   // forward value
        double g;   // accumulated adjoint
        int a, b;   // input ids (-1 if unused)
        int op;     // 0=leaf, 1=add, 2=mul, 3=sin, 4=exp
        bool isConst;
    };

    std::vector<Node> ns;

    int constant(double v) {
        ns.push_back(Node{v, 0.0, -1, -1, 0, true});
        return (int)ns.size() - 1;
    }

    int input(double v) {
        ns.push_back(Node{v, 0.0, -1, -1, 0, false});
        return (int)ns.size() - 1;
    }

    int add(int a, int b) {
        double v = ns[a].v + ns[b].v;
        ns.push_back(Node{v, 0.0, a, b, 1, false});
        return (int)ns.size() - 1;
    }

    int mul(int a, int b) {
        double v = ns[a].v * ns[b].v;
        ns.push_back(Node{v, 0.0, a, b, 2, false});
        return (int)ns.size() - 1;
    }

    int sin_(int a) {
        double v = std::sin(ns[a].v);
        ns.push_back(Node{v, 0.0, a, -1, 3, false});
        return (int)ns.size() - 1;
    }

    int exp_(int a) {
        double v = std::exp(ns[a].v);
        ns.push_back(Node{v, 0.0, a, -1, 4, false});
        return (int)ns.size() - 1;
    }

    double value(int node) const {
        return ns[node].v;
    }

    void backward(int root) {
        ns[root].g = 1.0;
        // Recording order guarantees every node's inputs have smaller ids,
        // so a reverse sweep processes all consumers before their inputs.
        for (int i = (int)ns.size() - 1; i >= 0; --i) {
            const Node& n = ns[i];
            if (n.g == 0.0) continue;
            const double gi = n.g;
            switch (n.op) {
                case 1:  // add: d/da = 1, d/db = 1
                    if (!ns[n.a].isConst) ns[n.a].g += gi;
                    if (!ns[n.b].isConst) ns[n.b].g += gi;
                    break;
                case 2:  // mul: d/da = b, d/db = a
                    if (!ns[n.a].isConst) ns[n.a].g += gi * ns[n.b].v;
                    if (!ns[n.b].isConst) ns[n.b].g += gi * ns[n.a].v;
                    break;
                case 3:  // sin: d/da = cos(a)
                    if (!ns[n.a].isConst) ns[n.a].g += gi * std::cos(ns[n.a].v);
                    break;
                case 4:  // exp: d/da = exp(a) = value
                    if (!ns[n.a].isConst) ns[n.a].g += gi * ns[n.a].v;
                    break;
                default:
                    break;
            }
        }
    }

    double grad(int node) const {
        return ns[node].g;
    }
};
